"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type ArcSelectOption = {
  id: string;
  label: string;
};

export type ArcSelectProps = {
  options: ArcSelectOption[];
  value?: string;
  defaultValue?: string;
  onValueChange?: (id: string) => void;
  className?: string;
  title?: string;
};

/**
 * Arc picker — options sit on a semicircle; selecting one animates the marker.
 */
function ArcSelect({
  options,
  value,
  defaultValue,
  onValueChange,
  className,
  title = "Pick",
}: ArcSelectProps) {
  const [internal, setInternal] = React.useState(
    defaultValue ?? options[0]?.id ?? "",
  );
  const current = value ?? internal;
  const idx = Math.max(
    0,
    options.findIndex((o) => o.id === current),
  );
  const selected = options[idx];

  const set = (id: string) => {
    if (value === undefined) setInternal(id);
    onValueChange?.(id);
  };

  const n = Math.max(options.length - 1, 1);

  return (
    <div className={cn("mx-auto w-full max-w-sm", className)}>
      <div className="relative h-36">
        <div
          aria-hidden
          className="absolute inset-x-6 top-8 h-24 rounded-t-full border border-border/80 border-b-0"
        />
        {options.map((opt, i) => {
          const t = options.length === 1 ? 0.5 : i / n;
          const angle = Math.PI - t * Math.PI;
          const x = 50 + Math.cos(angle) * 42;
          const y = 78 - Math.sin(angle) * 48;
          const active = opt.id === current;
          return (
            <button
              key={opt.id}
              type="button"
              onClick={() => set(opt.id)}
              className={cn(
                "absolute -translate-x-1/2 -translate-y-1/2 rounded-full border px-2.5 py-1 text-[11px] font-medium transition-all duration-200",
                active
                  ? "z-[2] border-primary bg-primary text-primary-foreground scale-110 shadow-[var(--shadow-lift)]"
                  : "z-[1] border-border bg-card text-muted-foreground hover:text-foreground",
              )}
              style={{ left: `${x}%`, top: `${y}%` }}
            >
              {opt.label}
            </button>
          );
        })}
        <div className="absolute bottom-1 left-0 right-0 text-center">
          <div className="text-[11px] text-muted-foreground">{title}</div>
          <div className="text-sm font-semibold">{selected?.label}</div>
        </div>
      </div>
    </div>
  );
}

export { ArcSelect };
